#include <stdio.h>

// Classic Tower of Hanoi in C
// Moves n disks from source rod to destination rod using auxiliary rod
void towerOfHanoi(int n, char from_rod, char to_rod, char aux_rod) {
    if (n == 1) {
        printf("Move disk 1 from rod %c to rod %c\n", from_rod, to_rod);
        return;
    }
    // Step 1: Move n-1 disks from source to aux using dest
    towerOfHanoi(n - 1, from_rod, aux_rod, to_rod);
    // Step 2: Move nth disk from source to dest
    printf("Move disk %d from rod %c to rod %c\n", n, from_rod, to_rod);
    // Step 3: Move n-1 disks from aux to dest using source
    towerOfHanoi(n - 1, aux_rod, to_rod, from_rod);
}

int main(void) {
    int n = 3; // Number of disks
    printf("--- Tower of Hanoi Solution for n = %d disks ---\n", n);
    towerOfHanoi(n, 'A', 'C', 'B');
    printf("Total moves required: 7\n");
    return 0;
}
